            Paragraph(Text("For every assignment compatible with the stated prefix whose original F1/F2 score is below scale, the response requires an assignment still below scale with strictly smaller finite lexicographic rank.")),
            Node("raw-cut-15872", "raw_cut_15872", "Original suffix at depth 13, code 111878, node 405724",
                "The statement is EJMOriginalReplayAssembly.Accepted at depth 13, code 111878 and original node 405724. Its checker retains remaining fuel 8, the full prefixCache and full prefixPartial. The proof transports the concrete memoized checker equation through check_eq_original at exactly this fuel, index, cache and partial assignment. Decoder memoization supplies equality; the concrete suffix check remains a separate premise of the transport.", DescribeRole.Theorem),
            Node("raw-cut-15999", "raw_cut_15999", "Original suffix at depth 13, code 112035, node 407714",
                "The statement is EJMOriginalReplayAssembly.Accepted at depth 13, code 112035 and original node 407714. Its checker retains remaining fuel 8, the full prefixCache and full prefixPartial. The proof transports the concrete memoized checker equation through check_eq_original at exactly this fuel, index, cache and partial assignment. Decoder memoization supplies equality; the concrete suffix check remains a separate premise of the transport.", DescribeRole.Theorem),
            Node("response-cut-15872", "response_cut_15872", "Canonical response for cut 15872",
